using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Mavis;
public static class AutoQaAircraftElapsedRegression{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);static void Prop(object o,string n,object v)=>o.GetType().GetProperty(n).SetValue(o,v);static void Call(object o,string n,params object[] v)=>o.GetType().GetMethod(n,F).Invoke(o,v);
 static void Check(List<object> rows,bool ok,string name)=>rows.Add(new{ok,name});
 public static object Run(string take){if(!Application.isPlaying||SceneManager.sceneCount!=1||!string.IsNullOrEmpty(SceneManager.GetActiveScene().path)||SessionState.GetBool("AUTO_QA.Aircraft013",false))throw new Exception("Isolated unowned Play required");if(File.Exists("AUTO_QA/Evidence/"+take+".json"))throw new Exception("Preserve evidence");SessionState.SetBool("AUTO_QA.Aircraft013",true);var rows=new List<object>();var cases=new List<object>();var root=new GameObject("AUTO_QA Aircraft elapsed");GameObject plane=null;string error=null;var origin=new Vector3(2500,500,2500);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.SetParent(root.transform);floor.transform.position=origin+Vector3.down*.5f;floor.transform.localScale=new Vector3(300,1,300);var ridge=GameObject.CreatePrimitive(PrimitiveType.Cube);ridge.transform.SetParent(root.transform);ridge.transform.position=origin+new Vector3(30,4,20);ridge.transform.localScale=new Vector3(20,8,80);var victim=new GameObject("AUTO_QA aircraft excluded target");victim.transform.SetParent(root.transform);victim.AddComponent<GameSaveExcluded>();victim.transform.position=origin+new Vector3(18,0,25);var capsule=victim.AddComponent<CharacterController>();capsule.height=2;capsule.center=Vector3.up;capsule.radius=.35f;var hp=victim.AddComponent<PlayerHealth>();hp.maxHealth=hp.currentHealth=1000;var ground=new[]{floor.GetComponent<Collider>(),ridge.GetComponent<Collider>()};var reference=new Dictionary<string,(Vector3 p,float angle)>();
 try{var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Prefabs/Bosses/BombardinoCrocodilo/BombardinoCrocodilo.prefab");foreach(string mode in new[]{"patrol","low scaled wings","returning","salvo","dead"})foreach(float requested in new[]{1f/60f,.125f,.3125f,1.25f}){plane=UnityEngine.Object.Instantiate(prefab,origin,Quaternion.identity);plane.AddComponent<GameSaveExcluded>();var boss=plane.GetComponent<BombardinoBoss>();boss.enabled=false;boss.target=victim.transform;Set(boss,"targetHealth",hp);Set(boss,"acquireAt",999f);Set(boss,"nextAttackAt",999f);Set(boss,"clock",0f);Set(boss,"age",0f);Prop(boss,"FightActive",false);
 if(mode=="low scaled wings"){boss.visual.localScale*=2;Prop(boss,"FightActive",true);Prop(boss,"CurrentAttack",BombardinoBoss.AttackKind.SpeedRun);Call(boss,"SetState",BombardinoBoss.State.Attack);plane.transform.position=new Vector3(plane.transform.position.x,504,plane.transform.position.z);}if(mode=="returning"){plane.GetComponent<Health>().currentHealth=50;Call(boss,"SetState",BombardinoBoss.State.Returning);}if(mode=="salvo"){plane.GetComponent<Health>().currentHealth=plane.GetComponent<Health>().maxHealth*.4f;Prop(boss,"FightActive",true);Prop(boss,"CurrentAttack",BombardinoBoss.AttackKind.MissileSalvo);Call(boss,"SetState",BombardinoBoss.State.Attack);Set(boss,"shotAt",0f);Set(boss,"shots",0);}if(mode=="dead")plane.GetComponent<Health>().Kill();Physics.SyncTransforms();var bodies=(Collider[])Get(boss,"bodyColliders");if(mode=="low scaled wings"){var probe=bodies.First(b=>b&&b.enabled&&!b.isTrigger&&b is BoxCollider);var virtualPlayer=probe.bounds.center-Vector3.up;Check(rows,Physics.ComputePenetration(probe,probe.transform.position,probe.transform.rotation,capsule,virtualPlayer,capsule.transform.rotation,out var cp,out float cd)&&cd>0,"Native body/player penetration positive control "+requested);var surface=ground[0];var virtualGround=surface.transform.position;virtualGround.y=probe.bounds.center.y;Check(rows,Physics.ComputePenetration(probe,probe.transform.position,probe.transform.rotation,surface,virtualGround,surface.transform.rotation,out var gp,out float gd)&&gd>0,"Native body/ground penetration positive control "+requested);}int penetrations=0;var contacts=new List<object>();float elapsed=0;int ticks=0;while(elapsed<1.25f-1e-6f){float delta=Mathf.Min(requested,1.25f-elapsed);boss.Tick(delta);elapsed+=delta;ticks++;Physics.SyncTransforms();if(mode=="low scaled wings")foreach(var body in bodies)if(body&&body.enabled&&!body.isTrigger){foreach(var surface in ground)if(Physics.ComputePenetration(body,body.transform.position,body.transform.rotation,surface,surface.transform.position,surface.transform.rotation,out var d,out float distance)&&distance>.001f){penetrations++;if(contacts.Count<4)contacts.Add(new{tick=ticks,body=body.name,surface=surface.name,distance,direction=d.ToString("F4"),position=plane.transform.position.ToString("F4"),bodyBounds=body.bounds.ToString(),surfaceBounds=surface.bounds.ToString(),resynchronizedClearance=((Vector3)typeof(BombardinoBoss).GetMethod("ClearGround",F).Invoke(boss,new object[]{plane.transform.position})).y});}if(Physics.ComputePenetration(body,body.transform.position,body.transform.rotation,capsule,capsule.transform.position,capsule.transform.rotation,out var pd,out float pDistance)&&pDistance>.001f)penetrations++;}}
 float clock=(float)Get(boss,"clock"),angle=(float)Get(boss,"orbitAngle");if(!reference.ContainsKey(mode))reference[mode]=(plane.transform.position,angle);var expected=reference[mode];float positionError=Vector3.Distance(plane.transform.position,expected.p);var deltaPosition=plane.transform.position-expected.p;float horizontalError=new Vector2(deltaPosition.x,deltaPosition.z).magnitude;float verticalError=Mathf.Abs(deltaPosition.y);Check(rows,Mathf.Abs(clock-1.25f)<.0001f,mode+"/"+requested+" consumes full elapsed time");Check(rows,horizontalError<.01f,mode+"/"+requested+" preserves horizontal trajectory");Check(rows,verticalError<=(mode=="dead"?.05f:boss.cruiseSpeed/60f+.002f),mode+"/"+requested+" vertical partition error stays within one bounded step");if(mode=="low scaled wings")Check(rows,penetrations==0,mode+"/"+requested+" native body clears floor, raised ridge and player capsule");if(mode=="returning")Check(rows,boss.CurrentState==BombardinoBoss.State.Patrol&&plane.GetComponent<Health>().currentHealth==plane.GetComponent<Health>().maxHealth,mode+"/"+requested+" completes return reset on time");if(mode=="salvo")Check(rows,boss.MissilesLaunched==8,mode+"/"+requested+" releases four authored missile pairs");cases.Add(new{mode,requested,ticks,clock,age=(float)Get(boss,"age"),positionError,horizontalError,verticalError,penetrations,contacts,missiles=boss.MissilesLaunched,state=boss.CurrentState.ToString()});UnityEngine.Object.DestroyImmediate(plane);plane=null;foreach(var payload in UnityEngine.Object.FindObjectsByType<BombardinoOrdnance>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(payload.gameObject);}
 }catch(Exception e){error=e.ToString();}finally{if(plane)UnityEngine.Object.DestroyImmediate(plane);UnityEngine.Object.DestroyImmediate(root);foreach(var payload in UnityEngine.Object.FindObjectsByType<BombardinoOrdnance>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(payload.gameObject);SessionState.SetBool("AUTO_QA.Aircraft013",false);}int passed=rows.Count(x=>(bool)x.GetType().GetProperty("ok").GetValue(x));var result=new{passed,total=rows.Count,error,rows,cases};File.WriteAllText("AUTO_QA/Evidence/"+take+".json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{passed,total=rows.Count,error,cases};}

 public static object Inputs(string take){if(!Application.isPlaying||SceneManager.sceneCount!=1||!string.IsNullOrEmpty(SceneManager.GetActiveScene().path))throw new Exception("Isolated Play required");var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(3500,499.5f,3500);floor.transform.localScale=new Vector3(300,1,300);var plane=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Prefabs/Bosses/BombardinoCrocodilo/BombardinoCrocodilo.prefab"),new Vector3(3500,500,3500),Quaternion.identity);var boss=plane.GetComponent<BombardinoBoss>();boss.enabled=false;var rows=new List<object>();try{var before=plane.transform.position;foreach(float dt in new[]{0f,-1f,float.NaN,float.PositiveInfinity,float.NegativeInfinity}){boss.Tick(dt);Check(rows,(float)Get(boss,"clock")==0&&plane.transform.position==before,"Invalid/zero elapsed input is inert: "+dt);}boss.Tick(.016f);Check(rows,Mathf.Abs((float)Get(boss,"clock")-.016f)<1e-6f,"Ordinary small step still advances exact elapsed time");}finally{UnityEngine.Object.DestroyImmediate(plane);UnityEngine.Object.DestroyImmediate(floor);}var result=new{rows};File.WriteAllText("AUTO_QA/Evidence/"+take+".json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
